//! Oracle regression tests against pooltool fixtures (M9, contract §M9).
//!
//! Fixtures live in `tests/fixtures/oracle/` and are generated by
//! `tools/fixtures/dump_pooltool.py` from ekiefl/pooltool (Apache-2.0)
//! configured with EXACTLY the pool-core v1 models, parameters, and table
//! geometry (provenance recorded per fixture).
//!
//! Gates (spec SC-003): event-type sequences match 100%, |Δt| ≤ [`TOL_TIME`]
//! = 1 µs per event by default, final resting positions ≤ 0.1 mm. Events
//! drifted by the documented `make_kiss` model difference (see [`TOL_TIME`])
//! are waived INDIVIDUALLY — per fixture, per event index, with reasons and
//! a still-enforced `bound` ceiling — in
//! `tests/fixtures/oracle/waivers.json`.
//!
//! The per-fixture comparisons are `#[ignore]`-by-default because the physics
//! leaves are placeholders in the M9 worktree; the integration phase
//! un-ignores them (task T020). The schema/geometry validation tests run
//! unconditionally so committed fixtures can never rot.
//!
//! POOLTOOL-PARITY CONVENTION (issue #77, the kernel API contract Amendment 018):
//! since the ball-ball Coulomb-cap fix, the parity condition is
//! `SimOptions::default()` PLUS the explicit legacy slip law
//! `ball_ball_slip_law: PostImpactNormalDelta` — pooltool carries the
//! pre-fix e_b-scaled law, so the corrected default diverges from these
//! fixtures on every slip-branch ball-ball impact by design (registered
//! evidence-based divergence, issue #87). The `RailSeat::Planar` precedent:
//! the oracle surface pins the legacy option; fixtures stay untouched.

use pool_core::resolve::strike::validate_shot;
use pool_core::{
    simulate, Ball, BallId, BallParams, BallState, CueParams, Event, EventKind, MotionState,
    ShotParams, SimOptions, SystemState, Table, Vec3,
};
use serde::Deserialize;
use std::path::{Path, PathBuf};

/// Default per-event time tolerance [s] — SC-003's 1 µs gate, enforced for
/// every event that is not explicitly waived.
///
/// The gate holds for every event UP TO AND INCLUDING the first ball-ball
/// collision on all fixtures (measured: |dt| ≤ 9.9e-7 on `bank_two_cushion`,
/// which has no ball-ball event and needs NO waivers, and 5.6e-17 on the
/// `straight_pot` BallBall itself). Downstream of a ball-ball collision the
/// engines' positional bookkeeping differs by design (pooltool `make_kiss`
/// re-seats impacting pairs to a ~1e-6 m gap; we resolve at the exact
/// quartic contact point), and cloth-friction chains amplify the O(µm)
/// difference into event-time drift up to ~1e-4 s. Those events are waived
/// INDIVIDUALLY in `tests/fixtures/oracle/waivers.json` ("time" check, with
/// per-event indices, the make_kiss reason, and a still-enforced `bound`
/// ceiling), so the tight gate holds wherever it can and every relaxation is
/// explicit and auditable (SC-003 "documented model-difference waivers").
const TOL_TIME: f64 = 1e-6;
/// SC-003 final-position tolerance [m] (met as specified; measured max
/// 7.9e-5 on `cut_30_side`).
const TOL_POS: f64 = 1e-4;

const FIXTURE_NAMES: [&str; 5] = [
    "straight_pot",
    "cut_30_side",
    "draw_shot",
    "bank_two_cushion",
    "three_ball_chain",
];

// --- fixture schema ---------------------------------------------------------

#[derive(Deserialize)]
struct Fixture {
    format: String,
    name: String,
    provenance: Provenance,
    scenario: Scenario,
    oracle: Oracle,
}

#[derive(Deserialize)]
struct Provenance {
    pooltool_commit: String,
    ball_params: FxBallParams,
    table: FxTable,
}

#[derive(Deserialize)]
struct FxBallParams {
    m: f64,
    r: f64,
    u_s: f64,
    u_r: f64,
    u_sp: f64,
    e_b: f64,
    e_c: f64,
    f_c: f64,
    g: f64,
}

#[derive(Deserialize)]
struct FxTable {
    preset: String,
    l: f64,
    w: f64,
    cushion_height: f64,
}

#[derive(Deserialize)]
struct Scenario {
    balls: Vec<ScnBall>,
    shot: FxShot,
}

#[derive(Deserialize)]
struct ScnBall {
    id: u8,
    x: f64,
    y: f64,
}

#[derive(Deserialize)]
struct FxShot {
    v0: f64,
    phi: f64,
    theta: f64,
    a: f64,
    b: f64,
    seed: u64,
}

#[derive(Deserialize)]
struct Oracle {
    events: Vec<FxEvent>,
    #[serde(rename = "final")]
    final_states: Vec<FxBall>,
}

#[derive(Deserialize)]
struct FxEvent {
    t: f64,
    #[serde(rename = "type")]
    kind: String,
    ids: Vec<u8>,
    index: Option<u16>,
    #[serde(rename = "from")]
    from_motion: Option<String>,
    #[serde(rename = "to")]
    to_motion: Option<String>,
    post: Vec<FxBall>,
}

#[derive(Deserialize)]
struct FxBall {
    id: u8,
    pos: [f64; 3],
    vel: [f64; 3],
    avel: [f64; 3],
    motion: String,
}

#[derive(Deserialize)]
struct WaiverFile {
    format: String,
    waivers: Vec<Waiver>,
}

#[derive(Deserialize)]
struct Waiver {
    fixture: String,
    check: String,
    event: Option<usize>,
    /// Multi-event form of `event` (schema v1 extension): the waiver applies
    /// to every listed event index.
    events: Option<Vec<usize>>,
    ball: Option<u8>,
    /// For "time" waivers: |dt| ceiling [s] still ENFORCED on waived events
    /// (a waiver relaxes the strict gate; it never removes the check).
    bound: Option<f64>,
    reason: String,
}

impl Waiver {
    fn applies_to_event(&self, event: Option<usize>) -> bool {
        match (&self.event, &self.events) {
            (None, None) => true,
            (Some(e), _) => Some(*e) == event,
            (None, Some(list)) => event.is_some_and(|e| list.contains(&e)),
        }
    }
}

#[derive(Deserialize)]
struct TableGeometry {
    format: String,
    linear: Vec<GeoLinear>,
    circular: Vec<GeoCircular>,
    pockets: Vec<GeoPocket>,
}

#[derive(Deserialize)]
struct GeoLinear {
    index: usize,
    p1: [f64; 2],
    p2: [f64; 2],
    height: f64,
}

#[derive(Deserialize)]
struct GeoCircular {
    index: usize,
    center: [f64; 2],
    radius: f64,
    height: f64,
}

#[derive(Deserialize)]
struct GeoPocket {
    index: usize,
    center: [f64; 2],
    radius: f64,
}

// --- loading ----------------------------------------------------------------

fn fixtures_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures")
}

fn read_json<T: serde::de::DeserializeOwned>(path: &Path) -> T {
    let data = std::fs::read_to_string(path)
        .unwrap_or_else(|e| panic!("cannot read {}: {e}", path.display()));
    serde_json::from_str(&data).unwrap_or_else(|e| panic!("cannot parse {}: {e}", path.display()))
}

fn load_fixture(name: &str) -> Fixture {
    let fx: Fixture = read_json(&fixtures_dir().join(format!("oracle/{name}.json")));
    assert_eq!(fx.format, "openbilliards.oracle.v1");
    assert_eq!(fx.name, name);
    fx
}

fn load_waivers() -> Vec<Waiver> {
    let wf: WaiverFile = read_json(&fixtures_dir().join("oracle/waivers.json"));
    assert_eq!(wf.format, "openbilliards.oracle.waivers.v1");
    wf.waivers
}

fn find_waiver<'a>(
    waivers: &'a [Waiver],
    fixture: &str,
    check: &str,
    event: Option<usize>,
    ball: Option<u8>,
) -> Option<&'a Waiver> {
    waivers.iter().find(|w| {
        (w.fixture == "*" || w.fixture == fixture)
            && w.check == check
            && w.applies_to_event(event)
            && (w.ball.is_none() || w.ball == ball)
    })
}

fn waived(
    waivers: &[Waiver],
    fixture: &str,
    check: &str,
    event: Option<usize>,
    ball: Option<u8>,
) -> bool {
    find_waiver(waivers, fixture, check, event, ball).is_some()
}

fn motion_name(m: MotionState) -> &'static str {
    match m {
        MotionState::Stationary => "Stationary",
        MotionState::Spinning => "Spinning",
        MotionState::Sliding => "Sliding",
        MotionState::Rolling => "Rolling",
        MotionState::Pocketed => "Pocketed",
        MotionState::Airborne => "Airborne",
    }
}

const MOTION_NAMES: [&str; 5] = ["Stationary", "Spinning", "Sliding", "Rolling", "Pocketed"];

fn ball_params_from(p: &FxBallParams) -> BallParams {
    BallParams {
        m: p.m,
        r: p.r,
        u_s: p.u_s,
        u_r: p.u_r,
        u_sp: p.u_sp,
        e_b: p.e_b,
        e_c: p.e_c,
        f_c: p.f_c,
        // Fixtures predate Amendment 002 and are theta = 0 planar shots
        // (no slate bounce can occur); pin the default.
        e_t: 0.5,
    }
}

fn system_from(fx: &Fixture) -> SystemState {
    let params = ball_params_from(&fx.provenance.ball_params);
    let balls = fx
        .scenario
        .balls
        .iter()
        .map(|b| Ball {
            id: BallId(b.id),
            params,
            state: BallState {
                pos: Vec3::new(b.x, b.y, params.r),
                vel: Vec3::ZERO,
                avel: Vec3::ZERO,
                motion: MotionState::Stationary,
                pinch: None,
            },
        })
        .collect();
    SystemState {
        balls,
        table: Table::wpa_9ft(params.r),
        equipment: Default::default(),
    }
}

fn shot_from(fx: &Fixture) -> ShotParams {
    let s = &fx.scenario.shot;
    ShotParams {
        v0: s.v0,
        phi: s.phi,
        theta: s.theta,
        a: s.a,
        b: s.b,
        seed: s.seed,
    }
}

// --- event descriptors (structural comparison) -------------------------------

/// Engine-neutral event descriptor: kind + participants + geometry index +
/// transition labels. Two events "match" iff their descriptors are equal.
#[derive(PartialEq, Eq, Clone, Debug)]
struct EvKey {
    kind: String,
    ids: Vec<u8>,
    index: Option<u16>,
    from: Option<String>,
    to: Option<String>,
}

impl std::fmt::Display for EvKey {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}{:?}", self.kind, self.ids)?;
        if let Some(i) = self.index {
            write!(f, "[{i}]")?;
        }
        if let (Some(a), Some(b)) = (&self.from, &self.to) {
            write!(f, "({a}->{b})")?;
        }
        Ok(())
    }
}

fn key_of_fx(e: &FxEvent) -> EvKey {
    EvKey {
        kind: e.kind.clone(),
        ids: e.ids.clone(),
        index: e.index,
        from: e.from_motion.clone(),
        to: e.to_motion.clone(),
    }
}

fn key_of_ours(kind: &EventKind) -> EvKey {
    let (kind, ids, index, from, to) = match kind {
        EventKind::Strike { ball } => ("Strike", vec![ball.0], None, None, None),
        EventKind::BallBall { b1, b2 } => ("BallBall", vec![b1.0, b2.0], None, None, None),
        EventKind::BallLinearCushion { ball, seg } => {
            ("BallLinearCushion", vec![ball.0], Some(*seg), None, None)
        }
        EventKind::BallCircularCushion { ball, arc } => {
            ("BallCircularCushion", vec![ball.0], Some(*arc), None, None)
        }
        EventKind::BallPocket { ball, pocket } => {
            ("BallPocket", vec![ball.0], Some(*pocket), None, None)
        }
        EventKind::Transition { ball, from, to } => (
            "Transition",
            vec![ball.0],
            None,
            Some(motion_name(*from).to_string()),
            Some(motion_name(*to).to_string()),
        ),
        EventKind::BallTable { ball } => ("BallTable", vec![ball.0], None, None, None),
        EventKind::BallOffTable { ball } => ("BallOffTable", vec![ball.0], None, None, None),
        EventKind::Rest => ("Rest", vec![], None, None, None),
    };
    EvKey {
        kind: kind.to_string(),
        ids,
        index,
        from,
        to,
    }
}

fn stream_dump(keys: &[EvKey], ts: &[f64]) -> String {
    keys.iter()
        .zip(ts)
        .enumerate()
        .map(|(i, (k, t))| format!("  #{i:<3} t={t:<12.7} {k}"))
        .collect::<Vec<_>>()
        .join("\n")
}

// --- the oracle comparison ----------------------------------------------------

fn xy_dist(a: [f64; 3], b: Vec3) -> f64 {
    let (dx, dy) = (a[0] - b.x, a[1] - b.y);
    (dx * dx + dy * dy).sqrt()
}

fn xyz_dist(a: [f64; 3], b: Vec3) -> f64 {
    let (dx, dy, dz) = (a[0] - b.x, a[1] - b.y, a[2] - b.z);
    (dx * dx + dy * dy + dz * dz).sqrt()
}

/// Position distance honoring the pocketed-park-z waiver: pooltool and
/// pool-core park pocketed balls at the same pocket-center x/y but different
/// documented z depths.
fn pos_dist(fx_ball: &FxBall, ours: &BallState, pocketed_z_waived: bool) -> f64 {
    if fx_ball.motion == "Pocketed" && pocketed_z_waived {
        xy_dist(fx_ball.pos, ours.pos)
    } else {
        xyz_dist(fx_ball.pos, ours.pos)
    }
}

fn run_oracle(name: &str) {
    let fx = load_fixture(name);
    let waivers = load_waivers();
    let system = system_from(&fx);
    let shot = shot_from(&fx);
    // Pooltool-parity condition (issue #77, the kernel API contract Amendment 018):
    // pooltool carries the pre-fix e_b-scaled slip law, so the parity
    // surface is the EXPLICIT legacy option, not the corrected default —
    // the RailSeat::Planar oracle-parity precedent. Everything else stays
    // at the kernel default; fixtures are untouched.
    let opts = SimOptions {
        ball_ball_slip_law: pool_core::shot::BallBallSlipLaw::PostImpactNormalDelta,
        ..SimOptions::default()
    };

    let record =
        simulate(&system, &shot, &opts).unwrap_or_else(|e| panic!("{name}: simulate failed: {e}"));

    // Our stream minus the terminal Rest (bookkeeping event; no pooltool
    // counterpart).
    let ours: Vec<&Event> = record
        .events
        .iter()
        .filter(|e| !matches!(e.kind, EventKind::Rest))
        .collect();
    assert!(
        matches!(record.events.last().map(|e| &e.kind), Some(EventKind::Rest)),
        "{name}: record must terminate with Rest"
    );

    let our_keys: Vec<EvKey> = ours.iter().map(|e| key_of_ours(&e.kind)).collect();
    let our_ts: Vec<f64> = ours.iter().map(|e| e.t).collect();
    let fx_keys: Vec<EvKey> = fx.oracle.events.iter().map(key_of_fx).collect();
    let fx_ts: Vec<f64> = fx.oracle.events.iter().map(|e| e.t).collect();

    // 1. Event-type sequence equality (SC-003: 100%).
    assert_eq!(
        our_keys,
        fx_keys,
        "{name}: event sequence mismatch\n-- ours:\n{}\n-- oracle:\n{}",
        stream_dump(&our_keys, &our_ts),
        stream_dump(&fx_keys, &fx_ts),
    );

    // 2. Event times within 1 µs (SC-003), except explicitly waived events —
    //    which still must respect the waiver's documented `bound` ceiling.
    for (i, (fe, oe)) in fx.oracle.events.iter().zip(&ours).enumerate() {
        let dt = (fe.t - oe.t).abs();
        if let Some(w) = find_waiver(&waivers, name, "time", Some(i), None) {
            let bound = w.bound.unwrap_or(f64::INFINITY);
            assert!(
                dt <= bound,
                "{name}: event #{i} {} exceeds even its WAIVER bound: ours {} vs oracle {} \
                 (|dt| = {dt:.3e} > {bound:.0e}; waiver reason: {})",
                fx_keys[i],
                oe.t,
                fe.t,
                w.reason
            );
            continue;
        }
        assert!(
            dt <= TOL_TIME,
            "{name}: event #{i} {} time mismatch: ours {} vs oracle {} (|dt| = {dt:.3e} > {TOL_TIME:.0e})",
            fx_keys[i],
            oe.t,
            fe.t
        );
    }

    // 3. Final resting positions within 0.1 mm.
    let pocketed_z_waived = waived(&waivers, name, "pocketed_park_z", None, None);
    let mut finals: std::collections::BTreeMap<u8, BallState> =
        system.balls.iter().map(|b| (b.id.0, b.state)).collect();
    for e in &record.events {
        for (id, st) in &e.post {
            finals.insert(id.0, *st);
        }
    }
    for fb in &fx.oracle.final_states {
        if waived(&waivers, name, "final_pos", None, Some(fb.id)) {
            continue;
        }
        let ours = finals
            .get(&fb.id)
            .unwrap_or_else(|| panic!("{name}: ball {} missing from our record", fb.id));
        assert_eq!(
            motion_name(ours.motion),
            fb.motion,
            "{name}: ball {} final motion mismatch",
            fb.id
        );
        let d = pos_dist(fb, ours, pocketed_z_waived);
        assert!(
            d <= TOL_POS,
            "{name}: ball {} final position mismatch: ours {:?} vs oracle {:?} (|d| = {d:.3e} > {TOL_POS:.0e})",
            fb.id,
            ours.pos,
            fb.pos
        );
    }
}

// --- per-fixture oracle gates (integration un-ignores; T020) -----------------

macro_rules! oracle_test {
    ($test:ident, $name:literal) => {
        #[test]
        fn $test() {
            run_oracle($name);
        }
    };
}

oracle_test!(oracle_straight_pot, "straight_pot");
oracle_test!(oracle_cut_30_side, "cut_30_side");
oracle_test!(oracle_draw_shot, "draw_shot");
oracle_test!(oracle_bank_two_cushion, "bank_two_cushion");
oracle_test!(oracle_three_ball_chain, "three_ball_chain");

// --- always-on fixture validation (gates addendum) ----------------------------

/// Every committed oracle fixture parses and satisfies the schema invariants:
/// provenance pinned, parameters identical to pool-core defaults, well-formed
/// monotone event stream over known balls/geometry, resting final states.
#[test]
fn oracle_fixtures_parse_and_validate() {
    let waivers = load_waivers();
    for w in &waivers {
        assert!(
            matches!(
                w.check.as_str(),
                "pocketed_park_z" | "time" | "final_pos" | "event_pos"
            ),
            "unknown waiver check {:?}",
            w.check
        );
        assert!(
            w.fixture == "*" || FIXTURE_NAMES.contains(&w.fixture.as_str()),
            "waiver references unknown fixture {:?}",
            w.fixture
        );
        assert!(!w.reason.is_empty(), "waivers must document a reason");
        assert!(
            w.event.is_none() || w.events.is_none(),
            "waiver must not set both 'event' and 'events'"
        );
        if w.check == "time" {
            assert!(
                w.event.is_some() || w.events.as_ref().is_some_and(|l| !l.is_empty()),
                "time waivers must name specific event indices (no blanket waivers)"
            );
            let bound = w
                .bound
                .expect("time waivers must carry an enforced 'bound'");
            assert!(bound.is_finite() && bound > 0.0, "bad waiver bound {bound}");
        } else {
            assert!(w.bound.is_none(), "'bound' only applies to time waivers");
        }
    }

    let defaults = BallParams::default();
    for name in FIXTURE_NAMES {
        let fx = load_fixture(name);

        // Provenance is pinned and parameters are exactly ours.
        assert_eq!(
            fx.provenance.pooltool_commit.len(),
            40,
            "{name}: bad commit hash"
        );
        assert!(
            fx.provenance
                .pooltool_commit
                .chars()
                .all(|c| c.is_ascii_hexdigit()),
            "{name}: bad commit hash"
        );
        let p = &fx.provenance.ball_params;
        assert_eq!(ball_params_from(p), defaults, "{name}: ball params drifted");
        assert_eq!(p.g, pool_core::G, "{name}: gravity drifted");
        let t = &fx.provenance.table;
        assert_eq!(t.preset, "wpa_9ft");
        assert_eq!(t.l, 2.54);
        assert_eq!(t.w, 1.27);
        assert_eq!(t.cushion_height, 0.635 * 2.0 * defaults.r);

        // Scenario is a valid pool-core input.
        let shot = shot_from(&fx);
        // Oracle fixtures run on the default ball + default (nickel) cue.
        validate_shot(&shot, defaults.r, &CueParams::default())
            .unwrap_or_else(|e| panic!("{name}: invalid shot: {e}"));
        let system = system_from(&fx);
        let ids: Vec<u8> = fx.scenario.balls.iter().map(|b| b.id).collect();
        assert!(ids.contains(&0), "{name}: missing cue ball");
        for b in &system.balls {
            assert!(b.state.pos.x.abs() <= 1.27 / 2.0 - defaults.r);
            assert!(b.state.pos.y.abs() <= 2.54 / 2.0 - defaults.r);
        }
        for (i, a) in system.balls.iter().enumerate() {
            for b in &system.balls[i + 1..] {
                let gap = (a.state.pos - b.state.pos).norm() - 2.0 * defaults.r;
                assert!(gap > 0.0, "{name}: balls {:?}/{:?} overlap", a.id, b.id);
            }
        }

        // Event stream shape.
        let table = &system.table;
        let events = &fx.oracle.events;
        assert!(!events.is_empty(), "{name}: no events");
        assert_eq!(
            events[0].kind, "Strike",
            "{name}: first event must be Strike"
        );
        assert_eq!(events[0].t, 0.0);
        assert_eq!(events[0].ids, vec![0]);
        let mut t_prev = 0.0;
        for (i, e) in events.iter().enumerate() {
            assert!(
                e.t.is_finite() && e.t >= t_prev,
                "{name}: event #{i} time regressed"
            );
            t_prev = e.t;

            let mut sorted = e.ids.clone();
            sorted.sort_unstable();
            sorted.dedup();
            assert_eq!(sorted, e.ids, "{name}: event #{i} ids not sorted/unique");
            for id in &e.ids {
                assert!(ids.contains(id), "{name}: event #{i} unknown ball {id}");
            }

            let expect_ids = match e.kind.as_str() {
                "BallBall" => 2,
                "Strike"
                | "BallLinearCushion"
                | "BallCircularCushion"
                | "BallPocket"
                | "Transition" => 1,
                other => panic!("{name}: event #{i} unknown type {other:?}"),
            };
            assert_eq!(
                e.ids.len(),
                expect_ids,
                "{name}: event #{i} wrong participant count"
            );

            let index_bound = match e.kind.as_str() {
                "BallLinearCushion" => Some(table.linear.len()),
                "BallCircularCushion" => Some(table.circular.len()),
                "BallPocket" => Some(table.pockets.len()),
                _ => None,
            };
            match index_bound {
                Some(bound) => {
                    let idx = e.index.unwrap_or_else(|| {
                        panic!("{name}: event #{i} ({}) missing geometry index", e.kind)
                    });
                    assert!(
                        (idx as usize) < bound,
                        "{name}: event #{i} index out of range"
                    );
                }
                None => assert!(e.index.is_none(), "{name}: event #{i} unexpected index"),
            }

            if e.kind == "Transition" {
                let from = e.from_motion.as_deref().expect("Transition needs 'from'");
                let to = e.to_motion.as_deref().expect("Transition needs 'to'");
                assert!(MOTION_NAMES.contains(&from), "{name}: bad motion {from:?}");
                assert!(MOTION_NAMES.contains(&to), "{name}: bad motion {to:?}");
                assert_ne!(from, to, "{name}: event #{i} no-op transition");
            } else {
                assert!(e.from_motion.is_none() && e.to_motion.is_none());
            }

            let post_ids: Vec<u8> = e.post.iter().map(|b| b.id).collect();
            assert_eq!(post_ids, e.ids, "{name}: event #{i} post/ids mismatch");
            for b in &e.post {
                assert!(MOTION_NAMES.contains(&b.motion.as_str()));
                for v in b.pos.iter().chain(&b.vel).chain(&b.avel) {
                    assert!(v.is_finite(), "{name}: event #{i} non-finite post state");
                }
            }
        }

        // Final states: every scenario ball, at rest.
        let mut final_ids: Vec<u8> = fx.oracle.final_states.iter().map(|b| b.id).collect();
        final_ids.sort_unstable();
        let mut want = ids.clone();
        want.sort_unstable();
        assert_eq!(final_ids, want, "{name}: final states must cover all balls");
        for b in &fx.oracle.final_states {
            assert!(
                b.motion == "Stationary" || b.motion == "Pocketed",
                "{name}: ball {} final motion {:?} not at rest",
                b.id,
                b.motion
            );
        }
    }
}

/// The pool-cli scenario halves parse into the real pool-core types and agree
/// with the oracle fixtures they were generated alongside.
#[test]
fn scenario_files_parse_and_match_fixtures() {
    for name in FIXTURE_NAMES {
        let path = fixtures_dir().join(format!("scenarios/{name}.json"));
        let scn: serde_json::Value = read_json(&path);

        assert_eq!(
            scn["system"]["table"], "wpa_9ft",
            "{name}: scenario table preset"
        );
        let balls: Vec<Ball> = serde_json::from_value(scn["system"]["balls"].clone())
            .unwrap_or_else(|e| panic!("{name}: scenario balls: {e}"));
        let shot: ShotParams = serde_json::from_value(scn["shot"].clone())
            .unwrap_or_else(|e| panic!("{name}: scenario shot: {e}"));

        let fx = load_fixture(name);
        let fx_shot = shot_from(&fx);
        assert_eq!(shot, fx_shot, "{name}: scenario/fixture shot drifted");

        assert_eq!(balls.len(), fx.scenario.balls.len());
        for (b, fb) in balls.iter().zip(&fx.scenario.balls) {
            assert_eq!(b.id, BallId(fb.id));
            assert_eq!(
                b.params,
                BallParams::default(),
                "{name}: scenario params drifted"
            );
            assert_eq!(b.state.pos, Vec3::new(fb.x, fb.y, b.params.r));
            assert_eq!(b.state.vel, Vec3::ZERO);
            assert_eq!(b.state.avel, Vec3::ZERO);
            assert_eq!(b.state.motion, MotionState::Stationary);
        }
    }
}

/// The pooltool-built table used for the oracle dumps is geometrically
/// identical to `Table::wpa_9ft` (same segment/arc/pocket layout, same index
/// order, same WPA nose height) — otherwise the oracle would be invalid.
#[test]
fn table_geometry_matches_pooltool_dump() {
    const TOL: f64 = 1e-9; // trig via numpy vs libm: agree far below this

    let geo: TableGeometry = read_json(&fixtures_dir().join("oracle/table_geometry.json"));
    assert_eq!(geo.format, "openbilliards.table.v1");
    let table = Table::wpa_9ft(BallParams::default().r);

    assert_eq!(geo.linear.len(), table.linear.len());
    for g in &geo.linear {
        let s = &table.linear[g.index];
        let close = |p: [f64; 2], q: Vec3| (p[0] - q.x).abs() < TOL && (p[1] - q.y).abs() < TOL;
        // Endpoint order is a pool-core convention (playing area to the left
        // of p1->p2); compare as an unordered pair.
        assert!(
            (close(g.p1, s.p1) && close(g.p2, s.p2)) || (close(g.p1, s.p2) && close(g.p2, s.p1)),
            "linear[{}] endpoints mismatch: dump ({:?}, {:?}) vs ours ({:?}, {:?})",
            g.index,
            g.p1,
            g.p2,
            s.p1,
            s.p2
        );
        assert!(
            (g.height - s.height).abs() < TOL,
            "linear[{}] height",
            g.index
        );
    }

    assert_eq!(geo.circular.len(), table.circular.len());
    for g in &geo.circular {
        let a = &table.circular[g.index];
        assert!(
            (g.center[0] - a.center.x).abs() < TOL,
            "circular[{}] x",
            g.index
        );
        assert!(
            (g.center[1] - a.center.y).abs() < TOL,
            "circular[{}] y",
            g.index
        );
        assert!(
            (g.radius - a.radius).abs() < TOL,
            "circular[{}] radius",
            g.index
        );
        assert!(
            (g.height - a.height).abs() < TOL,
            "circular[{}] height",
            g.index
        );
    }

    assert_eq!(geo.pockets.len(), table.pockets.len());
    for g in &geo.pockets {
        let p = &table.pockets[g.index];
        assert!(
            (g.center[0] - p.center.x).abs() < TOL,
            "pocket[{}] x",
            g.index
        );
        assert!(
            (g.center[1] - p.center.y).abs() < TOL,
            "pocket[{}] y",
            g.index
        );
        assert!(
            (g.radius - p.radius).abs() < TOL,
            "pocket[{}] radius",
            g.index
        );
    }
}
